{"id":"core-rotacao-russa","nome":"Rotação russa","noPlano":true,"equipamento":"Em casa só com o corpo","equip":"solo-cruzado","equipamentoTipo":"Peso do corpo","musculoPrincipal":"Oblíquos","musculosSecundarios":["Reto abdominal","Transverso"],"tipoMovimento":"core","composto":false,"passoCargaKg":1,"cargaBaseKg":0,"nivel":"Intermediário","cuidado":"Coluna lombar","seriesPadrao":"3 × 16","descansoSeg":45,"descricao":"Giro controlado da caixa torácica sentado em equilíbrio para trabalho dos oblíquos.","comoFazer":["Sente no colchonete com os joelhos flexionados, calcanhares apoiados no chão e coluna longa.","Incline o tronco levemente para trás (cerca de 30 graus) mantendo o peito aberto.","Gire os ombros e o tórax juntos de um lado para o outro sem pressa.","Retorne ao centro a cada repetição mantendo o abdômen firme."],"errosComuns":["Bater apenas as mãos no chão de cada lado sem girar os ombros.","Arredondar a coluna lombar em formato de C.","Tirar os pés do chão com peso alto e sobrecarregar a lombar."],"dicas":["Mantenha os calcanhares apoiados no chão para proteger os discos lombares.","Acompanhe suas mãos com o olhar para garantir que o tronco inteiro gire."],"respiracao":"Expire ao girar para cada lado e inspire brevemente ao passar pelo centro.","avisoSeguranca":"Gire o tronco em bloco (não só os braços), faça sem pressa e mantenha os pés apoiados no chão.","sinonimos":["russian twist","giro russo","abdominal russo","rotacao de tronco sentado"],"grupo":"Core","subgrupo":"Oblíquos","porTempo":false,"erroComum":"Bater apenas as mãos no chão de cada lado sem girar os ombros.","imagem":{"mini":null,"grande":null},"oculto":false},
{"id":"core-roda-abdominal","nome":"Roda abdominal","noPlano":true,"equipamento":"Academia completa","equip":"corpo","equipamentoTipo":"Outros","musculoPrincipal":"Reto abdominal","musculosSecundarios":["Transverso","Dorsais","Tríceps"],"tipoMovimento":"core","composto":true,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Avançado","cuidado":"Coluna lombar","seriesPadrao":"3 × 10","descansoSeg":60,"descricao":"Extensão antiextensão com rodinha no solo para força avançada de todo o core.","comoFazer":["Ajoelhe sobre um colchonete macio segurando a roda abdominal abaixo dos ombros.","Encaixe a pelve em leve retroversão e contraia forte abdômen e glúteos.","Deslize a roda à frente apenas até onde você mantém a coluna neutra.","Puxe a roda de volta usando a força do abdômen e das dorsais."],"errosComuns":["Deixar a barriga cair e arquear a coluna lombar na extensão.","Sentar nos calcanhares antes de trazer os braços de volta.","Ir até o chão logo nas primeiras séries sem controle de core."],"dicas":["Faça de frente para uma parede a um metro para limitar a distância com segurança.","Mantenha o quadril e o tronco avançando juntos no mesmo ângulo."],"respiracao":"Inspire enquanto avança com a roda e solte o ar ao puxar de volta.","avisoSeguranca":"Nunca deixe a coluna lombar arquear; limite a distância à frente e pare imediatamente se doer.","sinonimos":["ab wheel","ab rollout","rodinha abdominal","abdominal com roda"],"grupo":"Core","subgrupo":"Estabilidade","porTempo":false,"erroComum":"Deixar a barriga cair e arquear a coluna lombar na extensão.","imagem":{"mini":null,"grande":null},"oculto":false},
{"id":"core-escalador","nome":"Escalador (mountain climber)","noPlano":true,"equipamento":"Em casa só com o corpo","equip":"corpo","equipamentoTipo":"Peso do corpo","musculoPrincipal":"Reto abdominal","musculosSecundarios":["Flexores do quadril","Deltoide anterior","Cardiovascular"],"tipoMovimento":"core","composto":true,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Iniciante","cuidado":"Punho","seriesPadrao":"3 × 30 s","descansoSeg":30,"descricao":"Alternância dinâmica de joelhos ao peito em posição de prancha alta para core e fôlego.","comoFazer":["Apoie as mãos no chão alinhadas exatamente abaixo dos ombros em prancha alta.","Firme o abdômen mantendo a coluna reta da cabeça aos calcanhares.","Traga um joelho em direção ao peito sem deixar o quadril subir.","Troque as pernas em ritmo controlado mantendo os ombros firmes sobre os punhos."],"errosComuns":["Empinar o quadril lá no alto transformando numa corrida no lugar.","Deixar as mãos longe demais à frente da linha dos ombros.","Bater os pés com força no piso."],"dicas":["Fazer devagar foca mais no abdômen; acelerar eleva mais o estímulo cardiovascular.","Espalhe bem os dedos das mãos no solo para aliviar os punhos."],"respiracao":"Mantenha respiração contínua e cadenciada ao longo dos 30 segundos.","avisoSeguranca":"Conserve os ombros alinhados sobre os punhos e não deixe a lombar afundar quando cansar.","sinonimos":["mountain climber","escalador no solo","abdominal escalador","corrida na prancha"],"grupo":"Core","subgrupo":"Abdômen","porTempo":true,"erroComum":"Empinar o quadril lá no alto transformando numa corrida no lugar.","imagem":{"mini":null,"grande":null},"oculto":false,"duracaoSerieSeg":30},
{"id":"core-lenhador-polia","nome":"Lenhador na polia","noPlano":true,"equipamento":"Academia completa","equip":"cabo-antirotacao","equipamentoTipo":"Polia","musculoPrincipal":"Oblíquos","musculosSecundarios":["Reto abdominal","Deltoide anterior","Glúteos"],"tipoMovimento":"core","composto":true,"passoCargaKg":2.5,"cargaBaseKg":12.5,"nivel":"Intermediário","cuidado":"Coluna lombar","seriesPadrao":"3 × 12","descansoSeg":45,"descricao":"Rotação diagonal com cabo para desenvolver potência nos oblíquos e transferência de força.","comoFazer":["Ajuste a polia no alto (ou na base) e posicione-se de lado com os pés além dos ombros.","Segure a alça com as duas mãos mantendo os braços quase estendidos.","Puxe o cabo na diagonal à frente do corpo girando o tronco e o pé de trás juntos.","Retorne devagar resistindo à tração do cabo e repita do outro lado."],"errosComuns":["Girar a coluna lombar mantendo os dois pés travados e imóveis no chão.","Puxar o cabo dobrando os cotovelos apenas com os braços.","Soltar o peso de forma brusca na volta."],"dicas":["Permita que o calcanhar de trás gire como numa tacada de tênis para proteger os joelhos e a lombar.","A força vem do giro do quadril e das costelas, não das mãos."],"respiracao":"Solte o ar ao puxar o cabo na diagonal e inspire no retorno controlado.","avisoSeguranca":"Gire o quadril e o pé de trás junto com o tronco para não torcer a coluna lombar.","sinonimos":["woodchopper","cable woodchop","lenhador no cabo","rotacao diagonal polia"],"grupo":"Core","subgrupo":"Oblíquos","porTempo":false,"erroComum":"Girar a coluna lombar mantendo os dois pés travados e imóveis no chão.","imagem":{"mini":null,"grande":null},"oculto":false},
{"id":"core-estabilizacao-alternada","nome":"Dead bug","noPlano":false,"equipamento":"Em casa só com o corpo","equip":"solo-cruzado","equipamentoTipo":"Peso do corpo","musculoPrincipal":"Transverso","musculosSecundarios":["Reto abdominal","Flexores do quadril"],"tipoMovimento":"core","composto":false,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Iniciante","cuidado":"Nenhum","seriesPadrao":"3 × 12","descansoSeg":25,"descricao":"Coordenação de braço e perna opostos com a lombar colada no solo para estabilidade profunda.","comoFazer":["Deite de barriga para cima, cole a lombar no chão e eleve braços para o teto e joelhos a 90 graus.","Inspire e pressione as costelas para baixo.","Estenda devagar um braço para trás e a perna oposta à frente sem tocar o chão.","Volte ao centro mantendo a lombar colada no colchonete e alterne os lados."],"errosComuns":["Deixar a lombar descolar do chão quando a perna estende.","Fazer o movimento apressado perdendo a coordenação.","Mover os dois braços ou as duas pernas do mesmo lado."],"dicas":["Imagine que há uma fita embaixo da sua lombar que ninguém pode puxar.","Se a lombar sair do chão, estenda a perna mais para o alto (45 graus)."],"respiracao":"Expire lentamente enquanto estende braço e perna opostos; inspire ao voltar ao centro.","avisoSeguranca":"Pare a extensão da perna no exato ponto em que você consegue manter a lombar colada no solo.","sinonimos":["estabilizacao alternada no solo","inseto morto","deadbug","core dead bug"],"grupo":"Core","subgrupo":"Estabilidade","porTempo":false,"erroComum":"Deixar a lombar descolar do chão quando a perna estende.","imagem":{"mini":null,"grande":null},"oculto":false},
{"id":"core-bird-dog","nome":"Bird dog","noPlano":true,"equipamento":"Em casa só com o corpo","equip":"corpo","equipamentoTipo":"Peso do corpo","musculoPrincipal":"Lombar","musculosSecundarios":["Glúteos","Transverso","Deltoide anterior"],"tipoMovimento":"core","composto":false,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Iniciante","cuidado":"Nenhum","seriesPadrao":"3 × 12","descansoSeg":25,"descricao":"Extensão cruzada em quatro apoios que fortalece lombar, glúteos e centro do corpo sem sobrecarga.","comoFazer":["Fique em quatro apoios sobre um colchonete com mãos sob os ombros e joelhos sob os quadris.","Trave o abdômen mantendo a coluna neutra e o olhar voltado para o chão.","Estenda um braço à frente e a perna oposta para trás até ficarem paralelos ao solo.","Segure dois segundos sem girar a bacia, volte ao apoio e troque o lado."],"errosComuns":["Chutar a perna para o alto arqueando a coluna lombar.","Abrir o quadril de lado e perder o equilíbrio.","Olhar para a frente forçando o pescoço."],"dicas":["Pense em alcançar longe para a frente e para trás, e não para cima.","Toque o cotovelo no joelho oposto embaixo do corpo antes de estender novamente."],"respiracao":"Solte o ar ao estender braço e perna opostos e inspire ao retornar.","avisoSeguranca":"Use um colchonete sob os joelhos e mantenha a perna na linha horizontal do tronco, sem arquear a lombar.","sinonimos":["perdigueiro","quadrupedia cruzada","birddog","extensao cruzada quatro apoios"],"grupo":"Core","subgrupo":"Estabilidade","porTempo":false,"erroComum":"Chutar a perna para o alto arqueando a coluna lombar.","imagem":{"mini":null,"grande":null},"oculto":false},
{"id":"cardio-corrida-esteira","nome":"Corrida na esteira","noPlano":true,"equipamento":"Academia completa","equip":"corrida-leve","equipamentoTipo":"Cardio","musculoPrincipal":"Cardiovascular","musculosSecundarios":["Quadríceps","Panturrilhas","Glúteos"],"tipoMovimento":"cardio","composto":true,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Iniciante","cuidado":"Joelho","seriesPadrao":"20 min · Esforço moderado","descansoSeg":0,"descricao":"Corrida contínua em esteira com amortecimento e controle preciso de velocidade e inclinação.","comoFazer":["Suba na esteira com os pés nas abas laterais, prenda o clipe de segurança e inicie caminhando.","Aqueça por 3 a 5 minutos em caminhada rápida ou trote leve.","Ajuste uma velocidade de esforço leve a moderado (em que consiga falar frases curtas).","Corra no centro da lona com postura alta e reduza para caminhada nos 3 minutos finais."],"errosComuns":["Correr segurando nas barras frontais ou laterais da esteira.","Olhar para os pés curvando o pescoço.","Pular da esteira ainda em movimento rápido."],"dicas":["Inclinação de 1% simula melhor a resistência natural do ar da rua.","Mantenha passos curtos e silenciosos abaixo do centro do corpo."],"respiracao":"Mantenha respiração cadenciada e natural compatível com o seu esforço percebido.","avisoSeguranca":"Prenda o clipe de parada de emergência na roupa e nunca desça da lona em movimento.","sinonimos":["treadmill run","esteira","correr na esteira","trote na esteira"],"grupo":"Cardio","subgrupo":"Corrida e caminhada","porTempo":true,"erroComum":"Correr segurando nas barras frontais ou laterais da esteira.","imagem":{"mini":null,"grande":null},"oculto":false,"duracaoSerieSeg":1200},
{"id":"cardio-caminhada-inclinada","nome":"Caminhada inclinada","noPlano":true,"equipamento":"Academia completa","equip":"corrida-leve","equipamentoTipo":"Cardio","musculoPrincipal":"Glúteos","musculosSecundarios":["Panturrilhas","Posterior de coxa","Cardiovascular"],"tipoMovimento":"cardio","composto":true,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Iniciante","cuidado":"Tornozelo","seriesPadrao":"20 min · Esforço moderado","descansoSeg":0,"descricao":"Caminhada em rampa na esteira para alto trabalho aeróbico e de pernas sem impacto de corrida.","comoFazer":["Inicie a esteira em velocidade de caminhada confortável no plano por 2 minutos.","Eleve gradualmente a inclinação (entre 5% e 12%) mantendo passo firme.","Caminhe com os braços livres balançando a 90 graus e o tronco levemente inclinado pelo tornozelo.","Zere a inclinação nos 2 minutos finais para desacelerar com calma."],"errosComuns":["Segurar no painel da esteira e inclinar o corpo para trás, anulando o efeito da rampa.","Dar passos largos demais batendo o calcanhar.","Colocar inclinação máxima com velocidade alta sem adaptação nos tendões."],"dicas":["Soltar as mãos das barras é o segredo para recrutar glúteos e core de verdade.","Se ofegar demais, diminua um pouco a velocidade antes de baixar a rampa."],"respiracao":"Inspire pelo nariz e solte o ar pela boca em ritmo constante.","avisoSeguranca":"Caminhe sem se pendurar no painel e progrida a inclinação aos poucos para proteger o tendão do calcâneo.","sinonimos":["incline walk","esteira inclinada","caminhada na rampa","caminhada esteira"],"grupo":"Cardio","subgrupo":"Corrida e caminhada","porTempo":true,"erroComum":"Segurar no painel da esteira e inclinar o corpo para trás, anulando o efeito da rampa.","imagem":{"mini":null,"grande":null},"oculto":false,"duracaoSerieSeg":1200},
{"id":"cardio-corrida-rua","nome":"Corrida na rua","noPlano":true,"equipamento":"Ao ar livre","equip":"rodagem-parque","equipamentoTipo":"Cardio","musculoPrincipal":"Cardiovascular","musculosSecundarios":["Quadríceps","Panturrilhas","Glúteos","Posterior de coxa"],"tipoMovimento":"cardio","composto":true,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Iniciante","cuidado":"Joelho","seriesPadrao":"25 min · Esforço leve a moderado","descansoSeg":0,"descricao":"Corrida ao ar livre guiada pelo esforço percebido para condicionamento aeróbico e resistência.","comoFazer":["Comece com 5 minutos de caminhada viva e mobilidade suave de tornozelos e quadris.","Inicie um trote em esforço leve a moderado, mantendo os ombros soltos e o olhar à frente.","Sustente cadência ritmada aterrissando o pé próximo à linha do quadril.","Encerre com 3 a 5 minutos de caminhada leve para normalizar a respiração."],"errosComuns":["Sair rápido demais nos primeiros minutos e ficar sem fôlego cedo.","Esticar a perna longe à frente travando o joelho no impacto.","Correr de fones altos sem atenção aos cruzamentos."],"dicas":["Para registrar mapa, distância e ritmo por km em tempo real, use a seção Tipos de corrida.","Intercale trote e caminhada nas primeiras semanas se estiver começando."],"respiracao":"Respire de forma fluida num ritmo em que você consiga conversar sem ofegar.","avisoSeguranca":"Use tênis adequado para corrida, aumente o volume semanal de forma gradual e mantenha atenção total ao trânsito.","sinonimos":["outdoor run","correr na rua","corrida no parque","corrida ao ar livre"],"grupo":"Cardio","subgrupo":"Corrida e caminhada","porTempo":true,"erroComum":"Sair rápido demais nos primeiros minutos e ficar sem fôlego cedo.","imagem":{"mini":null,"grande":null},"oculto":false,"duracaoSerieSeg":1500},
{"id":"cardio-tiros-esteira","nome":"Tiros na esteira","noPlano":true,"equipamento":"Academia completa","equip":"tiros","equipamentoTipo":"Cardio","musculoPrincipal":"Cardiovascular","musculosSecundarios":["Quadríceps","Posterior de coxa","Panturrilhas"],"tipoMovimento":"cardio","composto":true,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Intermediário","cuidado":"Joelho","seriesPadrao":"8 × 1 min forte · 1 min leve","descansoSeg":60,"descricao":"Treino intervalado na esteira alternando estímulos fortes e recuperação ativa.","comoFazer":["Faça 5 a 7 minutos obrigatórios de aquecimento em trote leve antes do primeiro tiro.","Ajuste a velocidade escolhida por você para um esforço forte, porém controlado, por 1 minuto.","Reduza a velocidade para trote leve ou caminhada rápida por 1 minuto de recuperação.","Repita os blocos programados e finalize com 4 minutos de caminhada calma."],"errosComuns":["Pular o aquecimento e entrar direto em alta velocidade.","Escolher uma velocidade acima do que sua passada suporta com equilíbrio.","Saltar para as abas laterais com a lona em alta velocidade."],"dicas":["Prefira reduzir a velocidade pelo botão da esteira em vez de pular para as bordas.","Mantenha o último tiro no mesmo controle técnico do primeiro."],"respiracao":"Recupere o fôlego com inspirações profundas durante os minutos leves.","avisoSeguranca":"Indicado apenas para quem já corre; aqueça sempre antes, escolha sua velocidade com prudência e use o clipe de segurança.","sinonimos":["treadmill intervals","hiit na esteira","intervalado na esteira","sprint esteira"],"grupo":"Cardio","subgrupo":"Corrida e caminhada","porTempo":true,"erroComum":"Pular o aquecimento e entrar direto em alta velocidade.","imagem":{"mini":null,"grande":null},"oculto":false,"duracaoSerieSeg":60},
{"id":"cardio-bicicleta-ergometrica","nome":"Bicicleta ergométrica","noPlano":true,"equipamento":"Academia completa","equip":"maquina","equipamentoTipo":"Cardio","musculoPrincipal":"Quadríceps","musculosSecundarios":["Cardiovascular","Panturrilhas","Glúteos"],"tipoMovimento":"cardio","composto":true,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Iniciante","cuidado":"Nenhum","seriesPadrao":"20 min · Esforço moderado","descansoSeg":0,"descricao":"Pedalada contínua sem impacto articular para condicionamento cardiovascular e resistência de pernas.","comoFazer":["Regule a altura do selim na linha do osso do quadril (no ponto baixo do pedal o joelho fica levemente flexionado).","Apoie a parte anterior dos pés nos pedais e ajuste as tiras de fixação.","Pedale em cadência fluida com carga leve a moderada mantendo a coluna alinhada.","Reduza a carga nos 2 minutos finais pedalando leve para voltar à calma."],"errosComuns":["Deixar o banco baixo demais sobrecarregando a frente dos joelhos.","Deixar o banco alto demais rebolando o quadril a cada pedalada.","Curvar as costas apoiando todo o peso nos punhos."],"dicas":["Excelente opção aeróbica para dias de recuperação ou sensibilidade nos tornozelos.","Mantenha os joelhos apontados para a frente, alinhados aos pedais."],"respiracao":"Respire de forma constante e confortável ao longo de todo o tempo.","avisoSeguranca":"Ajuste a altura do banco antes de começar para que o joelho nunca trave nem dobre excessivamente.","sinonimos":["stationary bike","ergometrica","bike ergometrica","bicicleta sentada"],"grupo":"Cardio","subgrupo":"Máquinas de cardio","porTempo":true,"erroComum":"Deixar o banco baixo demais sobrecarregando a frente dos joelhos.","imagem":{"mini":null,"grande":null},"oculto":false,"duracaoSerieSeg":1200},
{"id":"cardio-bicicleta-spinning","nome":"Bicicleta spinning","noPlano":true,"equipamento":"Academia completa","equip":"maquina","equipamentoTipo":"Cardio","musculoPrincipal":"Quadríceps","musculosSecundarios":["Glúteos","Panturrilhas","Cardiovascular"],"tipoMovimento":"cardio","composto":true,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Intermediário","cuidado":"Joelho","seriesPadrao":"25 min · Esforço moderado a forte","descansoSeg":0,"descricao":"Pedalada dinâmica em bike de roda de inércia alternando planos e subidas por esforço percebido.","comoFazer":["Ajuste a altura e a distância do selim e do guidão antes de subir na bike.","Aqueça 4 minutos em giro solto com resistência leve na roda.","Alterne blocos sentados em cadência viva e blocos com mais carga simulando subida.","Alivie a carga gradualmente nos 3 minutos finais sem parar os pés de repente."],"errosComuns":["Pedalar em pé sem carga suficiente na roda, deixando os pedais girarem soltos.","Travar os pedais de vez enquanto a roda de inércia gira rápido.","Apoiar o peso do tronco sobre o guidão quando pedala em pé."],"dicas":["Mantenha sempre uma resistência mínima na roda para proteger os joelhos.","Use o freio de emergência se precisar parar a roda rapidamente."],"respiracao":"Sincronize a respiração profunda com a cadência da pedalada.","avisoSeguranca":"Nunca pare os pés de golpe na bike de spinning; desacelere gradualmente ou acione o freio da roda.","sinonimos":["spinning","indoor cycling","bike spinning","aula de spinning"],"grupo":"Cardio","subgrupo":"Máquinas de cardio","porTempo":true,"erroComum":"Pedalar em pé sem carga suficiente na roda, deixando os pedais girarem soltos.","imagem":{"mini":null,"grande":null},"oculto":false,"duracaoSerieSeg":1500},
{"id":"cardio-eliptico","nome":"Elíptico","noPlano":true,"equipamento":"Academia completa","equip":"maquina","equipamentoTipo":"Cardio","musculoPrincipal":"Cardiovascular","musculosSecundarios":["Quadríceps","Glúteos","Dorsais"],"tipoMovimento":"cardio","composto":true,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Iniciante","cuidado":"Nenhum","seriesPadrao":"20 min · Esforço moderado","descansoSeg":0,"descricao":"Movimento cíclico de braços e pernas sem impacto, integrando membros inferiores e superiores.","comoFazer":["Suba nos pedais do elíptico segurando primeiro nas alças fixas centrais.","Inicie o movimento oval contínuo mantendo os pés inteiros apoiados nas plataformas.","Segure nas hastes móveis empurrando e puxando em conjunto com as pernas.","Desacelere nos 2 minutos finais e aguarde os pedais pararem totalmente antes de descer."],"errosComuns":["Ficar apenas na ponta dos pés deixando os calcanhares dormentes.","Inclinar o tronco sobre o painel do aparelho.","Colocar carga tão pesada que obrigue a dar trancos com o quadril."],"dicas":["Pressionar os calcanhares nos pedais ativa muito mais os glúteos e posteriores.","Manter a postura alta deixa a respiração livre e confortável."],"respiracao":"Mantenha respiração ritmada em esforço leve a moderado.","avisoSeguranca":"Espere os pedais pararem por completo antes de subir ou descer do aparelho elíptico.","sinonimos":["transport","elliptical","aparelho eliptico","eliptico transport"],"grupo":"Cardio","subgrupo":"Máquinas de cardio","porTempo":true,"erroComum":"Ficar apenas na ponta dos pés deixando os calcanhares dormentes.","imagem":{"mini":null,"grande":null},"oculto":false,"duracaoSerieSeg":1200},
{"id":"cardio-remo-ergometrico","nome":"Remo ergométrico","noPlano":true,"equipamento":"Academia completa","equip":"maquina","equipamentoTipo":"Cardio","musculoPrincipal":"Dorsais","musculosSecundarios":["Quadríceps","Cardiovascular","Bíceps","Lombar"],"tipoMovimento":"cardio","composto":true,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Intermediário","cuidado":"Coluna lombar","seriesPadrao":"15 min · Esforço moderado","descansoSeg":0,"descricao":"Cardio completo de baixo impacto que combina empurrão potente das pernas e puxada dorsal.","comoFazer":["Sente no carrinho, prenda as tiras sobre o meio dos pés e segure a manopla com braços estendidos.","Empurre primeiro com as pernas mantendo a coluna neutra e os braços retos.","Quando as pernas estenderem, incline levemente o tronco para trás e puxe a manopla até as costelas.","Volte na ordem inversa: estenda os braços, incline o tronco à frente e só então dobre os joelhos."],"errosComuns":["Dobrar os joelhos cedo demais na volta, fazendo a manopla bater neles.","Puxar com os braços antes de empurrar com as pernas.","Arredondar a coluna lombar e colocar o regulador de ar sempre no 10."],"dicas":["Memorize a sequência: pernas, tronco, braços na ida; braços, tronco, pernas na volta.","Regulagem de ar entre 4 e 6 simula a água real e preserva a lombar."],"respiracao":"Solte o ar com firmeza na puxada e inspire enquanto desliza à frente.","avisoSeguranca":"Mantenha a coluna neutra e inicie cada remada pela força das pernas para proteger a lombar.","sinonimos":["rowing machine","ergometro de remo","remo indoor","concept2"],"grupo":"Cardio","subgrupo":"Máquinas de cardio","porTempo":true,"erroComum":"Dobrar os joelhos cedo demais na volta, fazendo a manopla bater neles.","imagem":{"mini":null,"grande":null},"oculto":false,"duracaoSerieSeg":900},
{"id":"cardio-simulador-escada","nome":"Simulador de escada","noPlano":true,"equipamento":"Academia completa","equip":"degrau","equipamentoTipo":"Cardio","musculoPrincipal":"Glúteos","musculosSecundarios":["Quadríceps","Panturrilhas","Cardiovascular"],"tipoMovimento":"cardio","composto":true,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Intermediário","cuidado":"Joelho","seriesPadrao":"15 min · Esforço moderado","descansoSeg":0,"descricao":"Subida contínua de degraus para alto condicionamento cardiorrespiratório e resistência de glúteos e coxas.","comoFazer":["Suba no aparelho com ele parado, segure de leve nos apoios laterais e inicie em velocidade baixa.","Apoie o pé inteiro em cada degrau mantendo o tronco ereto e o abdômen ativo.","Suba em cadência constante em esforço moderado sem descarregar o peso nos braços.","Reduza a velocidade no último minuto e acione o botão de parada antes de descer."],"errosComuns":["Debruçar os antebraços no painel jogando o peso do corpo nas mãos.","Pisar apenas com a pontinha dos dedos na beirada do degrau.","Dar passos curtos e corridos olhando para baixo."],"dicas":["Use os corrimãos apenas com a ponta dos dedos para equilíbrio.","Subir degraus inteiros em ritmo moderado ativa mais os glúteos do que correr rápido."],"respiracao":"Respire de forma profunda e cadenciada durante toda a subida.","avisoSeguranca":"Apoie o pé inteiro no degrau para não escorregar e pare totalmente a escada antes de descer.","sinonimos":["stairmaster","escada ergometrica","stair climber","escada academia"],"grupo":"Cardio","subgrupo":"Máquinas de cardio","porTempo":true,"erroComum":"Debruçar os antebraços no painel jogando o peso do corpo nas mãos.","imagem":{"mini":null,"grande":null},"oculto":false,"duracaoSerieSeg":900},
{"id":"cardio-pular-corda","nome":"Pular corda","noPlano":true,"equipamento":"Em casa só com o corpo","equip":"corpo","equipamentoTipo":"Cardio","musculoPrincipal":"Panturrilhas","musculosSecundarios":["Cardiovascular","Quadríceps","Antebraço"],"tipoMovimento":"cardio","composto":true,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Intermediário","cuidado":"Tornozelo","seriesPadrao":"5 × 1 min","descansoSeg":30,"descricao":"Saltos curtos e ritmados com corda para coordenação, agilidade e capacidade aeróbica.","comoFazer":["Ajuste o comprimento da corda (pisando no meio, as manoplas chegam perto das axilas).","Mantenha os cotovelos próximos às costelas e gire a corda principalmente pelos punhos.","Salte apenas 2 a 3 centímetros do solo na parte anterior dos pés com os joelhos destravados.","Aterrisse de forma macia e silenciosa em cada giro."],"errosComuns":["Dar saltos altos demais dobrando os joelhos para trás.","Girar os braços inteiros abertos pelos ombros.","Pular descalço ou em piso de concreto duro sem amortecimento."],"dicas":["Olhe para um ponto fixo à frente e deixe o som dos pés bem baixinho.","Se estiver começando, intercale 30 segundos pulando por 30 segundos descansando."],"respiracao":"Mantenha respiração nasal ou oronasal contínua sem prender o ar.","avisoSeguranca":"Use tênis com bom amortecimento e aterrisse sempre com os joelhos levemente flexionados para absorver o impacto.","sinonimos":["jump rope","corda de pular","saltar corda","cardio com corda"],"grupo":"Cardio","subgrupo":"Calistenia e impacto","porTempo":true,"erroComum":"Dar saltos altos demais dobrando os joelhos para trás.","imagem":{"mini":null,"grande":null},"oculto":false,"duracaoSerieSeg":60},
{"id":"cardio-polichinelo","nome":"Polichinelo","noPlano":true,"equipamento":"Em casa só com o corpo","equip":"corpo","equipamentoTipo":"Peso do corpo","musculoPrincipal":"Cardiovascular","musculosSecundarios":["Panturrilhas","Deltoide lateral","Glúteo médio"],"tipoMovimento":"cardio","composto":true,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Iniciante","cuidado":"Tornozelo","seriesPadrao":"3 × 45 s","descansoSeg":20,"descricao":"Movimento clássico de abertura coordenada de braços e pernas para aquecimento e fôlego.","comoFazer":["Comece em pé com os pés unidos, joelhos destravados e braços ao lado do corpo.","Salte afastando os pés pouco além da largura dos ombros enquanto eleva os braços acima da cabeça.","Amorteça a descida na parte anterior dos pés mantendo os joelhos alinhados.","Salte novamente unindo os pés e trazendo os braços de volta à lateral."],"errosComuns":["Aterrissar com os joelhos duros e travados.","Deixar os joelhos caírem para dentro ao abrir a base.","Encolher o pescoço ao levantar os braços."],"dicas":["Se quiser versão sem impacto, dê um passo lateral de cada vez sem saltar.","Mantenha os braços em leve arco confortável para os ombros."],"respiracao":"Respire de forma ritmada acompanhando a abertura e o fechamento dos braços.","avisoSeguranca":"Aterrisse sempre com os joelhos levemente flexionados para reduzir o impacto nas articulações.","sinonimos":["jumping jacks","polichinelos","salto polichinelo"],"grupo":"Cardio","subgrupo":"Calistenia e impacto","porTempo":true,"erroComum":"Aterrissar com os joelhos duros e travados.","imagem":{"mini":null,"grande":null},"oculto":false,"duracaoSerieSeg":45},
{"id":"cardio-burpee","nome":"Burpee","noPlano":true,"equipamento":"Em casa só com o corpo","equip":"corpo","equipamentoTipo":"Peso do corpo","musculoPrincipal":"Corpo todo","musculosSecundarios":["Peitoral","Quadríceps","Reto abdominal","Cardiovascular"],"tipoMovimento":"cardio","composto":true,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Avançado","cuidado":"Punho","seriesPadrao":"3 × 30 s","descansoSeg":45,"descricao":"Sequência integrada de agachamento, prancha e salto vertical para condicionamento global.","comoFazer":["Em pé com os pés na largura dos ombros, agache e apoie as mãos firmes no chão à frente.","Leve os pés para trás em posição de prancha alta mantendo o abdômen travado.","Opcionalmente desça o peito ao solo e empurre de volta à prancha.","Traga os pés de volta para perto das mãos com a planta inteira no chão e suba num salto suave."],"errosComuns":["Deixar o quadril despencar e arquear a lombar ao jogar os pés para trás.","Voltar os pés apoiando apenas a ponta dos dedos e forçando os joelhos.","Aterrissar do salto final com as pernas rígidas."],"dicas":["Para versão intermediária sem impacto, leve e traga um pé de cada vez andando.","Priorize coluna firme na prancha acima de velocidade."],"respiracao":"Solte o ar ao recolher os pés e subir; inspire ao descer para a prancha.","avisoSeguranca":"Movimento de alto impacto: aterrisse com os joelhos flexionados e mantenha o abdômen firme ao entrar na prancha.","sinonimos":["burpees","meio burpee","sprawl","burpee completo"],"grupo":"Cardio","subgrupo":"Calistenia e impacto","porTempo":true,"erroComum":"Deixar o quadril despencar e arquear a lombar ao jogar os pés para trás.","imagem":{"mini":null,"grande":null},"oculto":false,"duracaoSerieSeg":30},
{"id":"mobilidade-alongamento-quadriceps","nome":"Alongamento de quadríceps","noPlano":true,"equipamento":"Em casa só com o corpo","equip":"corpo","equipamentoTipo":"Peso do corpo","musculoPrincipal":"Quadríceps","musculosSecundarios":["Flexores do quadril"],"tipoMovimento":"mobilidade","composto":false,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Iniciante","cuidado":"Joelho","seriesPadrao":"2 × 30 s por lado","descansoSeg":15,"descricao":"Alongamento em pé puxando o peito do pé em direção ao glúteo para aliviar a frente da coxa.","comoFazer":["Fique em pé ao lado de uma parede ou apoio firme para manter o equilíbrio.","Flexione um joelho e segure o peito do pé (ou tornozelo) com a mão do mesmo lado.","Mantenha os dois joelhos alinhados lado a lado e encaixe suavemente a pelve à frente.","Sustente por 30 segundos sem dor e troque de perna."],"errosComuns":["Abrir o joelho para o lado ou jogá-lo para a frente.","Arquear a coluna lombar para puxar mais o pé.","Puxar pelos dedos do pé torcendo o tornozelo."],"dicas":["Contrair levemente o glúteo do lado alongado intensifica o alongamento com segurança.","Se sentir pressão no joelho, use uma toalha ao redor do tornozelo e puxe menos."],"respiracao":"Respire de forma lenta e profunda, relaxando a coxa a cada expiração.","avisoSeguranca":"Nunca balance a perna, alongue sem dor, respire normalmente e evite alongar com o músculo frio.","sinonimos":["quad stretch","alongar coxa em pe","alongamento anterior de coxa"],"grupo":"Mobilidade","subgrupo":"Membros inferiores","porTempo":true,"erroComum":"Abrir o joelho para o lado ou jogá-lo para a frente.","imagem":{"mini":null,"grande":null},"oculto":false,"duracaoSerieSeg":30},
{"id":"mobilidade-alongamento-mundo","nome":"Alongamento de posterior","noPlano":false,"equipamento":"Em casa só com o corpo","equip":"isquiotibiais","equipamentoTipo":"Peso do corpo","musculoPrincipal":"Posterior de coxa","musculosSecundarios":["Panturrilhas","Lombar"],"tipoMovimento":"mobilidade","composto":false,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Iniciante","cuidado":"Coluna lombar","seriesPadrao":"2 × 30 s por lado","descansoSeg":15,"descricao":"Alongamento sentado ou em apoio para a cadeia posterior da coxa com coluna alinhada.","comoFazer":["Sente no colchonete com uma perna estendida à frente e a outra flexionada com a sola na coxa.","Cresça o topo da cabeça para o alto abrindo o peito.","Incline o tronco à frente a partir da dobra do quadril (não curvando as costas).","Apoie as mãos na canela ou no tornozelo, sustente por 30 segundos e troque de lado."],"errosComuns":["Arredondar a coluna lombar e o pescoço tentando alcançar a ponta do pé à força.","Dar trancos ou insistências rápidas para frente e para trás.","Prender o fôlego enquanto sente tensão."],"dicas":["Manter a coluna longa e descer 15 centímetros alonga melhor o posterior do que curvar as costas.","Você também pode passar uma faixa ou toalha na planta do pé."],"respiracao":"Inspire crescendo a coluna e solte o ar relaxando a parte de trás da coxa.","avisoSeguranca":"Nunca balance o tronco, mantenha amplitude sem dor, respire normalmente e não alongue com o músculo frio.","sinonimos":["alongamento ativo de posteriores","hamstring stretch","alongar isquiotibiais","alongamento posterior de coxa"],"grupo":"Mobilidade","subgrupo":"Membros inferiores","porTempo":true,"erroComum":"Arredondar a coluna lombar e o pescoço tentando alcançar a ponta do pé à força.","imagem":{"mini":null,"grande":null},"oculto":false,"duracaoSerieSeg":30},
{"id":"mobilidade-alongamento-peitoral","nome":"Alongamento de peitoral","noPlano":true,"equipamento":"Em casa só com o corpo","equip":"corpo","equipamentoTipo":"Peso do corpo","musculoPrincipal":"Peitoral","musculosSecundarios":["Deltoide anterior","Bíceps"],"tipoMovimento":"mobilidade","composto":false,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Iniciante","cuidado":"Ombro","seriesPadrao":"2 × 30 s por lado","descansoSeg":15,"descricao":"Abertura torácica apoiando o antebraço no batente ou parede para soltar peitoral e ombros.","comoFazer":["Posicione-se ao lado de uma parede ou batente de porta com os pés em base alternada.","Apoie o antebraço na parede com o cotovelo na linha do ombro (ou levemente abaixo).","Gire suavemente o peito e o tronco para o lado oposto até sentir o peitoral alongar.","Sustente por 30 segundos com os ombros baixos e repita do outro lado."],"errosComuns":["Subir o ombro junto à orelha durante o alongamento.","Projetar a cabeça e a barriga para a frente.","Forçar além do limite articular da cápsula anterior do ombro."],"dicas":["Abaixar o cotovelo alguns centímetros é mais confortável se seu ombro for sensível.","Ótimo para melhorar a postura após horas sentado."],"respiracao":"Mantenha respiração calma abrindo a caixa torácica na inspiração.","avisoSeguranca":"Não faça movimentos bruscos nem balance o tronco; mantenha sem dor e não alongue a frio.","sinonimos":["doorway chest stretch","alongar peito na parede","abertura de peitoral"],"grupo":"Mobilidade","subgrupo":"Membros superiores","porTempo":true,"erroComum":"Subir o ombro junto à orelha durante o alongamento.","imagem":{"mini":null,"grande":null},"oculto":false,"duracaoSerieSeg":30},
{"id":"mobilidade-gato-camelo","nome":"Alongamento de dorsal (gato-vaca)","noPlano":false,"equipamento":"Em casa só com o corpo","equip":"coluna","equipamentoTipo":"Peso do corpo","musculoPrincipal":"Dorsais","musculosSecundarios":["Lombar","Trapézio","Reto abdominal"],"tipoMovimento":"mobilidade","composto":false,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Iniciante","cuidado":"Nenhum","seriesPadrao":"2 × 35 s","descansoSeg":15,"descricao":"Mobilização fluida da coluna em quatro apoios alternando flexão e extensão suave.","comoFazer":["Posicione mãos abaixo dos ombros e joelhos abaixo dos quadris sobre o colchonete.","Solte o ar enquanto arredonda as costas para o teto, afastando as escápulas e soltando o pescoço.","Inspire enquanto abre o peito à frente e deixa a coluna descer suavemente.","Alterne os dois movimentos de forma lenta e contínua por 35 segundos."],"errosComuns":["Mover a coluna rápido demais sem sincronizar com a respiração.","Dobrar os cotovelos durante a transição.","Forçar o pescoço demais para trás na fase de abertura."],"dicas":["Inicie cada onda a partir do movimento da bacia, vértebra por vértebra.","Empurre o chão com as palmas para alongar bem a região entre as escápulas."],"respiracao":"Expire ao arredondar as costas para o alto e inspire ao abrir o tórax.","avisoSeguranca":"Vá apenas até onde for confortável sem dor, mantenha fluidez sem trancos e respire naturalmente.","sinonimos":["mobilidade de coluna em quatro apoios","gato vaca","cat cow","gato e vaca"],"grupo":"Mobilidade","subgrupo":"Coluna e tronco","porTempo":true,"erroComum":"Mover a coluna rápido demais sem sincronizar com a respiração.","imagem":{"mini":null,"grande":null},"oculto":false,"duracaoSerieSeg":35},
{"id":"mobilidade-alongamento-ombro","nome":"Alongamento de ombro","noPlano":true,"equipamento":"Em casa só com o corpo","equip":"ombro","equipamentoTipo":"Peso do corpo","musculoPrincipal":"Deltoide posterior","musculosSecundarios":["Deltoide lateral","Trapézio"],"tipoMovimento":"mobilidade","composto":false,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Iniciante","cuidado":"Ombro","seriesPadrao":"2 × 30 s por lado","descansoSeg":15,"descricao":"Tração horizontal suave do braço à frente do peito para aliviar a parte posterior do ombro.","comoFazer":["Fique em pé ou sentado com a coluna ereta e relaxe os dois ombros para baixo.","Cruze um braço estendido horizontalmente à frente do peito.","Use a outra mão no antebraço (nunca em cima do cotovelo) para puxar suavemente na direção do peito.","Sustente por 30 segundos respirando fundo e troque de braço."],"errosComuns":["Deixar o ombro alongado subir até encostar no queixo.","Girar o tronco inteiro junto com o braço.","Fazer pressão direta sobre a articulação do cotovelo."],"dicas":["Abaixar ativamente a escápula do braço cruzado multiplica a sensação de alívio.","Mantenha o olhar à frente e o pescoço destensionado."],"respiracao":"Respire normalmente soltando a tensão dos ombros a cada expiração.","avisoSeguranca":"Nunca balance nem force dor articular; mantenha a respiração livre e não alongue a frio.","sinonimos":["cross body shoulder stretch","alongar deltoide","alongamento de ombros"],"grupo":"Mobilidade","subgrupo":"Membros superiores","porTempo":true,"erroComum":"Deixar o ombro alongado subir até encostar no queixo.","imagem":{"mini":null,"grande":null},"oculto":false,"duracaoSerieSeg":30},
{"id":"mobilidade-alongamento-triceps","nome":"Alongamento de tríceps","noPlano":true,"equipamento":"Em casa só com o corpo","equip":"corpo","equipamentoTipo":"Peso do corpo","musculoPrincipal":"Tríceps","musculosSecundarios":["Dorsais","Deltoide posterior"],"tipoMovimento":"mobilidade","composto":false,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Iniciante","cuidado":"Ombro","seriesPadrao":"2 × 30 s por lado","descansoSeg":15,"descricao":"Alongamento acima da cabeça flexionando o cotovelo atrás da nuca para tríceps e lateral dorsal.","comoFazer":["Em pé ou sentado com postura firme, eleve um braço e dobre o cotovelo levando a mão entre as escápulas.","Apoie a outra mão suavemente sobre o cotovelo elevado.","Guie o cotovelo levemente para trás e para baixo sem empurrar a cabeça para a frente.","Sustente por 30 segundos com o abdômen ativo e repita no outro braço."],"errosComuns":["Pressionar o braço contra a nuca entortando o pescoço para baixo.","Arquear excessivamente a coluna lombar projetando as costelas.","Forçar além da mobilidade confortável do ombro."],"dicas":["Mantenha a cabeça erguida empurrando levemente a nuca para trás.","Inclinar o tronco dois centímetros para o lado oposto alonga também a dorsal."],"respiracao":"Inspire e expire com calma sem prender o ar durante os 30 segundos.","avisoSeguranca":"Alongue sem balançar e sem dor, mantendo o pescoço livre e o músculo previamente aquecido.","sinonimos":["overhead triceps stretch","alongar triceps","alongamento de braco acima da cabeca"],"grupo":"Mobilidade","subgrupo":"Membros superiores","porTempo":true,"erroComum":"Pressionar o braço contra a nuca entortando o pescoço para baixo.","imagem":{"mini":null,"grande":null},"oculto":false,"duracaoSerieSeg":30},
{"id":"mobilidade-alongamento-gluteo-figura-4","nome":"Alongamento de glúteo (figura 4)","noPlano":true,"equipamento":"Em casa só com o corpo","equip":"quadril","equipamentoTipo":"Peso do corpo","musculoPrincipal":"Glúteos","musculosSecundarios":["Glúteo médio","Lombar"],"tipoMovimento":"mobilidade","composto":false,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Iniciante","cuidado":"Joelho","seriesPadrao":"2 × 30 s por lado","descansoSeg":15,"descricao":"Alongamento deitado cruzando o tornozelo sobre a coxa oposta para liberar glúteos e piriforme.","comoFazer":["Deite de barriga para cima no colchonete com os dois joelhos flexionados.","Cruze o tornozelo direito sobre a coxa esquerda, logo acima do joelho, formando o número 4.","Passe as mãos por trás da coxa esquerda e puxe suavemente na direção do peito.","Mantenha a cabeça e os ombros relaxados no chão por 30 segundos e troque o lado."],"errosComuns":["Levantar a cabeça e os ombros do colchonete fazendo força no pescoço.","Apoiar o osso do tornozelo diretamente em cima da patela.","Deixar o pé da perna cruzada totalmente frouxo."],"dicas":["Manter o tornozelo cruzado a 90 graus (ponta do pé puxada) protege a lateral do joelho.","Se não alcançar a coxa sem tirar a cabeça do chão, use uma toalha atrás da coxa."],"respiracao":"Solte o ar devagar permitindo que o quadril relaxe a cada respiração.","avisoSeguranca":"Mantenha sem dor no joelho, nunca balance, respire normalmente e evite alongar com o músculo frio.","sinonimos":["figura 4","figure 4 stretch","alongamento piriforme","alongar gluteo deitado"],"grupo":"Mobilidade","subgrupo":"Membros inferiores","porTempo":true,"erroComum":"Levantar a cabeça e os ombros do colchonete fazendo força no pescoço.","imagem":{"mini":null,"grande":null},"oculto":false,"duracaoSerieSeg":30},
{"id":"mobilidade-alongamento-panturrilha","nome":"Alongamento de panturrilha","noPlano":true,"equipamento":"Em casa só com o corpo","equip":"tornozelo","equipamentoTipo":"Peso do corpo","musculoPrincipal":"Panturrilhas","musculosSecundarios":["Gastrocnêmio","Sóleo"],"tipoMovimento":"mobilidade","composto":false,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Iniciante","cuidado":"Tornozelo","seriesPadrao":"2 × 30 s por lado","descansoSeg":15,"descricao":"Alongamento em apoio na parede com a perna estendida atrás para gastrocnêmio e tendão.","comoFazer":["Fique de frente para uma parede, apoie as mãos na altura dos ombros e dê um passo para trás.","Aponte os dois pés diretamente para a frente (paralelos como trilhos de trem).","Mantenha o joelho de trás estendido e o calcanhar totalmente colado no chão.","Avance suavemente o quadril em direção à parede por 30 segundos e troque de perna."],"errosComuns":["Deixar o pé de trás virado para fora, perdendo o alinhamento da panturrilha.","Levantar o calcanhar de trás do piso.","Dar empurrões bruscos contra a parede."],"dicas":["Para alongar também o sóleo, dobre levemente o joelho de trás mantendo o calcanhar no chão.","Excelente após caminhadas e corridas."],"respiracao":"Respire de forma tranquila e contínua sem prender o fôlego.","avisoSeguranca":"Nunca balance o calcanhar, respeite a amplitude sem dor e não alongue com o músculo frio.","sinonimos":["calf stretch","alongar gemeos na parede","alongamento de gastrocnemio"],"grupo":"Mobilidade","subgrupo":"Membros inferiores","porTempo":true,"erroComum":"Deixar o pé de trás virado para fora, perdendo o alinhamento da panturrilha.","imagem":{"mini":null,"grande":null},"oculto":false,"duracaoSerieSeg":30},
{"id":"mobilidade-alongamento-flexor-quadril","nome":"Alongamento de flexor de quadril","noPlano":true,"equipamento":"Em casa só com o corpo","equip":"quadril","equipamentoTipo":"Peso do corpo","musculoPrincipal":"Flexores do quadril","musculosSecundarios":["Quadríceps","Glúteos"],"tipoMovimento":"mobilidade","composto":false,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Iniciante","cuidado":"Joelho","seriesPadrao":"2 × 30 s por lado","descansoSeg":15,"descricao":"Posição semi-ajoelhada com encaixe pélvico para aliviar o iliopsoas e a frente do quadril.","comoFazer":["Ajoelhe com um joelho apoiado no colchonete e o outro pé plantado à frente a 90 graus.","Mantenha o tronco vertical e encaixe a bacia para dentro contraindo o glúteo de trás.","Deslize o quadril apenas dois ou três centímetros à frente até sentir a virilha alongar.","Sustente por 30 segundos respirando fundo e troque o lado."],"errosComuns":["Jogar o quadril longe à frente arqueando a coluna lombar.","Inclinar o peito sobre a coxa da frente.","Apoiar o joelho direto no piso duro sem proteção."],"dicas":["Contrair o glúteo da perna apoiada no chão é o que alonga o psoas sem forçar a lombar.","Elevar o braço do mesmo lado do joelho no chão intensifica o alongamento."],"respiracao":"Inspire profundamente e solte o ar relaxando a parte frontal do quadril.","avisoSeguranca":"Use colchonete macio sob o joelho, não arqueie a lombar, mantenha sem dor e não alongue a frio.","sinonimos":["hip flexor stretch","alongar iliopsoas","alongamento de psoas","flexor de quadril"],"grupo":"Mobilidade","subgrupo":"Membros inferiores","porTempo":true,"erroComum":"Jogar o quadril longe à frente arqueando a coluna lombar.","imagem":{"mini":null,"grande":null},"oculto":false,"duracaoSerieSeg":30},
{"id":"mobilidade-abertura-quadril-90","nome":"Mobilidade de quadril 90/90","noPlano":false,"equipamento":"Em casa só com o corpo","equip":"quadril","equipamentoTipo":"Peso do corpo","musculoPrincipal":"Glúteo médio","musculosSecundarios":["Glúteos","Adutores"],"tipoMovimento":"mobilidade","composto":false,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Iniciante","cuidado":"Quadril","seriesPadrao":"2 × 40 s","descansoSeg":15,"descricao":"Transição sentada com joelhos a 90 graus para liberar a rotação interna e externa do quadril.","comoFazer":["Sente no colchonete com a perna da frente e a de trás dobradas em ângulos de 90 graus.","Mantenha a coluna longa e apoie as mãos no chão atrás do quadril se precisar.","Gire os dois joelhos devagar para o outro lado mantendo os calcanhares no mesmo ponto.","Pause dois segundos em cada lado durante os 40 segundos da série."],"errosComuns":["Desabar a coluna arredondada para trás.","Girar rápido demais dando tranco nos joelhos.","Prender a respiração nas trocas de lado."],"dicas":["Conforme ganhar mobilidade, faça a transição sem apoiar as mãos no chão.","Mantenha os tornozelos em 90 graus para estabilizar os joelhos."],"respiracao":"Inspire ao passar pelo centro e solte o ar ao pousar os joelhos de cada lado.","avisoSeguranca":"Respeite a rotação natural do seu quadril sem forçar dor nos joelhos e mantenha respiração fluida.","sinonimos":["transicao de quadril 90 90","90/90","90 90 hip mobility","mobilidade 90 90"],"grupo":"Mobilidade","subgrupo":"Membros inferiores","porTempo":true,"erroComum":"Desabar a coluna arredondada para trás.","imagem":{"mini":null,"grande":null},"oculto":false,"duracaoSerieSeg":40},
{"id":"mobilidade-rotacao-toracica","nome":"Rotação torácica","noPlano":false,"equipamento":"Em casa só com o corpo","equip":"toracica","equipamentoTipo":"Peso do corpo","musculoPrincipal":"Dorsais","musculosSecundarios":["Oblíquos","Peitoral","Deltoide posterior"],"tipoMovimento":"mobilidade","composto":false,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Iniciante","cuidado":"Nenhum","seriesPadrao":"2 × 35 s","descansoSeg":15,"descricao":"Abertura rotacional da parte média das costas em quatro apoios para postura e saúde dos ombros.","comoFazer":["Em quatro apoios no colchonete, mantenha o quadril estável sobre os joelhos.","Apoie uma mão de leve atrás da orelha sem puxar a cabeça.","Leve o cotovelo na direção do punho apoiado no chão.","Gire o tórax abrindo o peito e apontando o cotovelo para o teto, depois troque de lado."],"errosComuns":["Deslocar a bacia para o lado fingindo que girou o tórax.","Puxar a nuca com a mão.","Fazer o giro com pressa."],"dicas":["Empurre o chão firme com a mão de apoio para ganhar mais abertura.","Acompanhe o cotovelo com o olhar durante a subida."],"respiracao":"Inspire ao abrir o peito para o alto e solte o ar ao retornar.","avisoSeguranca":"Gire apenas até sua amplitude confortável sem forçar a lombar e mantenha respiração contínua.","sinonimos":["rotacao toracica e ombros","thoracic rotation","mobilidade toracica","abertura toracica"],"grupo":"Mobilidade","subgrupo":"Coluna e tronco","porTempo":true,"erroComum":"Deslocar a bacia para o lado fingindo que girou o tórax.","imagem":{"mini":null,"grande":null},"oculto":false,"duracaoSerieSeg":35},
{"id":"mobilidade-postura-crianca","nome":"Postura da criança","noPlano":true,"equipamento":"Em casa só com o corpo","equip":"coluna","equipamentoTipo":"Peso do corpo","musculoPrincipal":"Lombar","musculosSecundarios":["Dorsais","Glúteos"],"tipoMovimento":"mobilidade","composto":false,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Iniciante","cuidado":"Joelho","seriesPadrao":"2 × 40 s","descansoSeg":15,"descricao":"Posição restauradora ajoelhada com braços à frente para descomprimir a lombar e alongar dorsais.","comoFazer":["Ajoelhe no colchonete, una a ponta dos pés atrás e afaste levemente os joelhos.","Sente os quadris para trás em direção aos calcanhares de forma confortável.","Estenda os braços à frente no chão e apoie a testa suavemente no colchonete.","Mantenha por 40 segundos respirando fundo pelas costas."],"errosComuns":["Forçar o quadril contra os calcanhares sentindo dor nos joelhos.","Tensionar o pescoço mantendo a cabeça erguida.","Prender o ar."],"dicas":["Coloque uma almofada ou toalha enrolada atrás dos joelhos se houver pressão articular.","Caminhar com as mãos um pouco para cada diagonal alonga cada lateral dorsal."],"respiracao":"Inspire sentindo as costelas posteriores expandirem e expire soltando o peso do tronco.","avisoSeguranca":"Vá apenas até onde for confortável; tenha cuidado especial se houver desconforto no joelho ou na lombar.","sinonimos":["child pose","balasana","alongamento prece","postura de descanso"],"grupo":"Mobilidade","subgrupo":"Coluna e tronco","porTempo":true,"erroComum":"Forçar o quadril contra os calcanhares sentindo dor nos joelhos.","imagem":{"mini":null,"grande":null},"oculto":false,"duracaoSerieSeg":40},
{"id":"mobilidade-extensao-coluna-cobra","nome":"Extensão de coluna (cobra)","noPlano":true,"equipamento":"Em casa só com o corpo","equip":"coluna","equipamentoTipo":"Peso do corpo","musculoPrincipal":"Reto abdominal","musculosSecundarios":["Lombar","Flexores do quadril"],"tipoMovimento":"mobilidade","composto":false,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Iniciante","cuidado":"Coluna lombar","seriesPadrao":"2 × 25 s","descansoSeg":15,"descricao":"Extensão suave do tronco deitado de bruços para alongar a parede abdominal e mobilizar a coluna.","comoFazer":["Deite de barriga para baixo no colchonete com as pernas estendidas e o peito dos pés no solo.","Posicione os antebraços (ou as mãos) ao lado do peito com os ombros longe das orelhas.","Eleve suavemente o peito mantendo a pelve apoiada no chão.","Sustente numa altura confortável por 25 segundos e desça devagar."],"errosComuns":["Esticar totalmente os braços empurrando a lombar além do seu limite.","Encolher os ombros junto ao pescoço.","Jogar a cabeça para trás comprimindo a cervical."],"dicas":["Manter os antebraços no chão (postura da esfinge) é a versão mais gentil para a lombar.","Olhe para a frente mantendo o pescoço longo."],"respiracao":"Inspire ao abrir o peito suavemente e mantenha respiração calma no topo.","avisoSeguranca":"Suba apenas até onde for confortável sem comprimir a lombar; pare se houver qualquer dor na coluna.","sinonimos":["cobra","cobra stretch","bhujangasana","esfinge lombar"],"grupo":"Mobilidade","subgrupo":"Coluna e tronco","porTempo":true,"erroComum":"Esticar totalmente os braços empurrando a lombar além do seu limite.","imagem":{"mini":null,"grande":null},"oculto":false,"duracaoSerieSeg":25},
{"id":"mobilidade-joelhos-peito","nome":"Joelhos ao peito","noPlano":true,"equipamento":"Em casa só com o corpo","equip":"coluna","equipamentoTipo":"Peso do corpo","musculoPrincipal":"Lombar","musculosSecundarios":["Glúteos","Posterior de coxa"],"tipoMovimento":"mobilidade","composto":false,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Iniciante","cuidado":"Nenhum","seriesPadrao":"2 × 30 s","descansoSeg":15,"descricao":"Abraço suave das pernas deitado de costas para relaxar a musculatura lombar e glúteos.","comoFazer":["Deite de barriga para cima num colchonete confortável com a cabeça apoiada.","Traga os dois joelhos flexionados em direção ao peito.","Abrace as canelas (ou a parte de trás das coxas) deixando os ombros e o pescoço no chão.","Sustente por 30 segundos respirando devagar e apoie um pé de cada vez ao terminar."],"errosComuns":["Levantar a cabeça e tensionar o pescoço para alcançar as pernas.","Puxar com força excessiva tirando metade das costas do chão.","Soltar as duas pernas esticadas de uma vez no final."],"dicas":["Segurar atrás das coxas é mais confortável para os joelhos do que puxar pelas canelas.","Você pode balançar milímetros de um lado ao outro para massagear a região sacral."],"respiracao":"Solte o ar suavemente aproximando as coxas do abdômen.","avisoSeguranca":"Mantenha a cabeça apoiada no solo, nunca faça movimentos bruscos e respire normalmente sem dor.","sinonimos":["knees to chest","abracar os joelhos","alongamento lombar deitado"],"grupo":"Mobilidade","subgrupo":"Coluna e tronco","porTempo":true,"erroComum":"Levantar a cabeça e tensionar o pescoço para alcançar as pernas.","imagem":{"mini":null,"grande":null},"oculto":false,"duracaoSerieSeg":30},
{"id":"funcional-agachamento-salto","nome":"Agachamento com salto","noPlano":true,"equipamento":"Em casa só com o corpo","equip":"corpo","equipamentoTipo":"Peso do corpo","musculoPrincipal":"Quadríceps","musculosSecundarios":["Glúteos","Panturrilhas","Cardiovascular"],"tipoMovimento":"agachar","composto":true,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Intermediário","cuidado":"Joelho","seriesPadrao":"3 × 10","descansoSeg":60,"descricao":"Agachamento pliométrico com impulsão vertical e aterrissagem amortecida para potência de pernas.","comoFazer":["Afaste os pés na largura dos ombros com o peito aberto e o abdômen firme.","Desça em agachamento controlado levando os braços para trás.","Impulsione o chão estendendo tornozelos, joelhos e quadril num salto vertical suave.","Aterrisse da ponta do pé para o calcanhar já flexionando os joelhos para amortecer."],"errosComuns":["Aterrissar com os joelhos travados e barulhentos no chão.","Deixar os joelhos fecharem para dentro na saída ou na chegada do salto.","Curvar a lombar ao amortecer."],"dicas":["O segredo é pousar tão silencioso quanto possível, absorvendo a queda no agachamento.","Pause um segundo estabilizado na base antes do próximo salto."],"respiracao":"Inspire na descida e solte o ar durante o impulso vertical.","avisoSeguranca":"Exercício de impacto: aterrisse sempre com os joelhos flexionados e alinhados aos pés; evite se houver dor articular.","sinonimos":["jump squat","agachamento pliometrico","squat jump","salto agachado"],"grupo":"Funcional","subgrupo":"Potência e agilidade","porTempo":false,"erroComum":"Aterrissar com os joelhos travados e barulhentos no chão.","imagem":{"mini":null,"grande":null},"oculto":false},
{"id":"funcional-kettlebell-swing","nome":"Kettlebell swing","noPlano":true,"equipamento":"Academia completa","equip":"halteres-duplo","equipamentoTipo":"Kettlebell","musculoPrincipal":"Glúteos","musculosSecundarios":["Posterior de coxa","Lombar","Deltoide anterior"],"tipoMovimento":"dobradiça","composto":true,"passoCargaKg":2,"cargaBaseKg":12,"nivel":"Intermediário","cuidado":"Coluna lombar","seriesPadrao":"4 × 15","descansoSeg":60,"descricao":"Balanço explosivo de quadril com kettlebell para potência da cadeia posterior e condicionamento.","comoFazer":["Posicione o kettlebell um passo à frente, afaste os pés além do quadril e segure a alça com as duas mãos.","Puxe o peso para trás entre as coxas em movimento de dobradiça de quadril com coluna reta.","Estenda o quadril e os joelhos de forma potente, projetando o kettlebell até a linha do peito.","Deixe o peso descer livremente e absorva com o quadril indo para trás na próxima repetição."],"errosComuns":["Dobrar demais os joelhos transformando o swing num agachamento.","Fazer força com os ombros para levantar o kettlebell acima da cabeça.","Arredondar a coluna lombar no fundo ou hiperestender no topo."],"dicas":["Seus braços funcionam apenas como cordas: toda a força vem da extensão rápida do quadril.","Espere os antebraços tocarem o quadril na descida antes de dobrar a bacia."],"respiracao":"Inspire ao receber o kettlebell entre as pernas e solte o ar com vigor ao estender o quadril.","avisoSeguranca":"É um movimento de dobradiça do quadril (não é agachamento); mantenha a coluna neutra do início ao fim.","sinonimos":["kettlebell","swing russo","russian kettlebell swing","balanco com kettlebell"],"grupo":"Funcional","subgrupo":"Força integrada","porTempo":false,"erroComum":"Dobrar demais os joelhos transformando o swing num agachamento.","imagem":{"mini":null,"grande":null},"oculto":false},
{"id":"funcional-levantamento-turco","nome":"Levantamento turco","noPlano":true,"equipamento":"Academia completa","equip":"halteres-alto","equipamentoTipo":"Kettlebell","musculoPrincipal":"Corpo todo","musculosSecundarios":["Deltoide anterior","Oblíquos","Glúteos"],"tipoMovimento":"empurrar","composto":true,"passoCargaKg":1,"cargaBaseKg":8,"nivel":"Avançado","cuidado":"Ombro","seriesPadrao":"3 × 3 por lado","descansoSeg":75,"descricao":"Transição completa do solo até ficar em pé sustentando o peso acima da cabeça com estabilidade.","comoFazer":["Deite de costas e estenda um braço verticalmente para o teto mantendo o joelho do mesmo lado dobrado.","Suba apoiando primeiro o cotovelo e depois a mão livre no chão com o olhar no peso.","Eleve o quadril e passe a perna estendida para trás até ficar semi-ajoelhado.","Suba para a posição em pé e desça refazendo exatamente os mesmos passos com calma."],"errosComuns":["Perder a verticalidade do braço que sustenta o peso.","Tirar os olhos da carga nas transições.","Fazer o movimento rápido pulando etapas."],"dicas":["Domine cada etapa equilibrando um tênis sobre o punho fechado antes de usar peso.","Mantenha o ombro encaixado longe da orelha durante toda a subida e a descida."],"respiracao":"Respire de forma controlada a cada etapa de transição sem prender o ar.","avisoSeguranca":"Movimento técnico avançado: aprenda e comece sem carga antes de usar halter ou kettlebell leve.","sinonimos":["turkish get up","tgu","get up turco","levantamento turco com kettlebell"],"grupo":"Funcional","subgrupo":"Força integrada","porTempo":false,"erroComum":"Perder a verticalidade do braço que sustenta o peso.","imagem":{"mini":null,"grande":null},"oculto":false},
{"id":"funcional-wall-ball","nome":"Wall ball","noPlano":true,"equipamento":"Academia completa","equip":"halteres-alto","equipamentoTipo":"Outros","musculoPrincipal":"Quadríceps","musculosSecundarios":["Deltoide anterior","Glúteos","Tríceps"],"tipoMovimento":"agachar","composto":true,"passoCargaKg":1,"cargaBaseKg":6,"nivel":"Intermediário","cuidado":"Joelho","seriesPadrao":"3 × 15","descansoSeg":60,"descricao":"Agachamento integrado ao lançamento vertical de medicine ball na parede para força e resistência.","comoFazer":["Fique a um braço de distância da parede segurando a bola medicinal na altura do queixo.","Agache mantendo o peito alto, a coluna neutra e a bola próxima ao esterno.","Suba com potência e aproveite o embalo das pernas para lançar a bola no alvo na parede.","Receba a bola com os braços semiflexionados já amortecendo no próximo agachamento."],"errosComuns":["Ficar longe demais da parede e jogar a bola para a frente curvando as costas.","Tentar lançar a bola usando só os braços sem o impulso das pernas.","Deixar a bola bater no rosto por perder o foco visual."],"dicas":["Mantenha os cotovelos apontados para baixo e à frente sob a bola.","Acompanhe a trajetória da bola com os olhos o tempo todo."],"respiracao":"Inspire ao receber a bola e agachar; solte o ar ao subir e lançar.","avisoSeguranca":"Mantenha os joelhos alinhados aos pés, comece com bola leve (3 a 6 kg) e nunca tire os olhos da bola.","sinonimos":["wallball","lancamento de bola na parede","agachamento com medicine ball"],"grupo":"Funcional","subgrupo":"Potência e agilidade","porTempo":false,"erroComum":"Ficar longe demais da parede e jogar a bola para a frente curvando as costas.","imagem":{"mini":null,"grande":null},"oculto":false},
{"id":"funcional-thruster","nome":"Thruster","noPlano":true,"equipamento":"Em casa com halteres","equip":"halteres-alto","equipamentoTipo":"Halteres","musculoPrincipal":"Quadríceps","musculosSecundarios":["Deltoide anterior","Glúteos","Tríceps"],"tipoMovimento":"agachar","composto":true,"passoCargaKg":1,"cargaBaseKg":10,"nivel":"Intermediário","cuidado":"Ombro","seriesPadrao":"4 × 10","descansoSeg":75,"descricao":"Combinação fluida de agachamento frontal e desenvolvimento acima da cabeça num movimento único.","comoFazer":["Segure um par de halteres (ou barra) apoiado sobre a parte frontal dos ombros.","Agache mantendo o tronco ereto, o abdômen firme e os cotovelos apontados à frente.","Suba com velocidade transferindo a força das pernas para empurrar os pesos acima da cabeça.","Desça os halteres de volta aos ombros com controle antes de iniciar a próxima descida."],"errosComuns":["Pausar no meio da subida e tentar desenvolver o peso só com os ombros.","Arquear a lombar ao estender os braços acima da cabeça.","Deixar os joelhos fecharem para dentro na saída do agachamento."],"dicas":["Espere o quadril quase estender para disparar os braços para cima.","Respire no topo com os braços estendidos para manter o ritmo."],"respiracao":"Inspire na descida do agachamento e expire forte ao empurrar os pesos para o teto.","avisoSeguranca":"Mantenha os joelhos alinhados aos pés e a coluna neutra; comece com carga leve até dominar o ritmo.","sinonimos":["dumbbell thruster","thruster com barra","agachamento com desenvolvimento"],"grupo":"Funcional","subgrupo":"Força integrada","porTempo":false,"erroComum":"Pausar no meio da subida e tentar desenvolver o peso só com os ombros.","imagem":{"mini":null,"grande":null},"oculto":false},
{"id":"funcional-corda-naval","nome":"Corda naval","noPlano":true,"equipamento":"Academia completa","equip":"polia","equipamentoTipo":"Outros","musculoPrincipal":"Deltoide anterior","musculosSecundarios":["Braquiorradial","Reto abdominal","Cardiovascular"],"tipoMovimento":"core","composto":true,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Intermediário","cuidado":"Ombro","seriesPadrao":"4 × 30 s","descansoSeg":45,"descricao":"Ondas alternadas com corda pesada em base atlética para resistência de ombros, core e cardio.","comoFazer":["Segure as pontas da corda naval com um passo para a frente para deixar leve folga.","Flexione quadris e joelhos em base atlética com peito aberto e abdômen contraído.","Movimente os braços alternadamente para cima e para baixo criando ondas contínuas até a âncora.","Mantenha o ritmo por 30 segundos sem balançar a coluna."],"errosComuns":["Ficar com as pernas retas e jogar a coluna para trás.","Tensionar o pescoço encolhendo o trapézio.","Segurar a corda esticada demais sem folga para ondular."],"dicas":["Ondas curtas e rápidas a partir dos cotovelos poupam os ombros e mantêm o ritmo.","Mantenha os pés firmes no chão como raízes."],"respiracao":"Respire de forma forte e contínua durante toda a série de 30 segundos.","avisoSeguranca":"Proteja ombros e punhos mantendo pegada neutra firme e respeite as pausas entre as séries.","sinonimos":["battle ropes","corda funcional","ondas na corda naval","battle rope"],"grupo":"Funcional","subgrupo":"Potência e agilidade","porTempo":true,"erroComum":"Ficar com as pernas retas e jogar a coluna para trás.","imagem":{"mini":null,"grande":null},"oculto":false,"duracaoSerieSeg":30},
{"id":"funcional-prancha-remada","nome":"Prancha com remada","noPlano":true,"equipamento":"Em casa com halteres","equip":"halteres","equipamentoTipo":"Halteres","musculoPrincipal":"Dorsais","musculosSecundarios":["Transverso","Oblíquos","Bíceps"],"tipoMovimento":"puxar","composto":true,"passoCargaKg":1,"cargaBaseKg":8,"nivel":"Avançado","cuidado":"Punho","seriesPadrao":"3 × 8 por lado","descansoSeg":60,"descricao":"Remada unilateral em posição de prancha alta sobre halteres sextavados para core e costas.","comoFazer":["Apoie as mãos sobre dois halteres sextavados estáveis no chão e afaste bem os pés em prancha.","Contraia forte glúteos e abdômen para travar o quadril paralelo ao piso.","Empurre um halter contra o chão enquanto puxa o outro até a lateral das costelas.","Devolva o halter ao solo sem impacto e repita com o outro braço."],"errosComuns":["Usar halteres redondos que podem rolar e torcer o punho.","Girar a bacia de lado a cada puxada.","Deixar o quadril afundar forçando a lombar."],"dicas":["Se não houver halteres sextavados, apoie a mão de base diretamente no chão e reme apenas um lado por vez.","Pés mais afastados são essenciais para impedir que o quadril gire."],"respiracao":"Expire ao puxar o halter para a costela e inspire ao apoiar no chão.","avisoSeguranca":"Use apenas halteres sextavados antiderrapantes (ou apoie a mão de base no chão) para proteger os punhos.","sinonimos":["renegade row","remada renegada","prancha remada com halteres"],"grupo":"Funcional","subgrupo":"Força integrada","porTempo":false,"erroComum":"Usar halteres redondos que podem rolar e torcer o punho.","imagem":{"mini":null,"grande":null},"oculto":false},
{"id":"funcional-clean-halteres","nome":"Clean com halteres","noPlano":true,"equipamento":"Em casa com halteres","equip":"halteres-duplo","equipamentoTipo":"Halteres","musculoPrincipal":"Glúteos","musculosSecundarios":["Posterior de coxa","Trapézio","Quadríceps"],"tipoMovimento":"dobradiça","composto":true,"passoCargaKg":1,"cargaBaseKg":10,"nivel":"Avançado","cuidado":"Coluna lombar","seriesPadrao":"4 × 8","descansoSeg":75,"descricao":"Arranque técnico de quadril levando os halteres das coxas até os ombros com potência.","comoFazer":["Fique em pé com os pés na largura do quadril segurando um halter em cada mão ao lado das coxas.","Leve o quadril levemente para trás com a coluna neutra e os joelhos flexionados.","Estenda quadril e joelhos com velocidade, puxando os halteres rente ao corpo.","Gire os cotovelos rapidamente para a frente recebendo os halteres sobre os ombros com joelhos macios."],"errosComuns":["Subir os halteres em arco aberto na frente como numa rosca bíceps.","Arredondar a lombar na saída do movimento.","Receber os pesos no topo com as pernas travadas."],"dicas":["A força vem do salto de extensão do quadril, e os halteres sobem colados à camiseta.","Amorteça a recepção flexionando suavemente os joelhos."],"respiracao":"Inspire na preparação e solte o ar ao receber os halteres nos ombros.","avisoSeguranca":"Exercício técnico avançado: comece sem carga ou com halteres bem leves e mantenha a coluna neutra.","sinonimos":["dumbbell clean","hang clean halteres","arremesso com halteres"],"grupo":"Funcional","subgrupo":"Potência e agilidade","porTempo":false,"erroComum":"Subir os halteres em arco aberto na frente como numa rosca bíceps.","imagem":{"mini":null,"grande":null},"oculto":false},
{"id":"funcional-caminhada-fazendeiro","nome":"Caminhada do fazendeiro","noPlano":true,"equipamento":"Em casa com halteres","equip":"halteres-duplo","equipamentoTipo":"Halteres","musculoPrincipal":"Trapézio","musculosSecundarios":["Antebraço","Transverso","Glúteo médio"],"tipoMovimento":"core","composto":true,"passoCargaKg":1,"cargaBaseKg":16,"nivel":"Iniciante","cuidado":"Coluna lombar","seriesPadrao":"4 × 40 s","descansoSeg":60,"descricao":"Caminhada postural carregando pesos ao lado do corpo para pegada, trapézio e estabilidade central.","comoFazer":["Posicione dois halteres ou kettlebells ao lado dos pés, agache com a coluna reta e segure firme.","Fique em pé abrindo o peito, encaixando os ombros e travando o abdômen.","Caminhe em passos curtos e firmes em linha reta mantendo o olhar no horizonte.","Ao concluir os 40 segundos, dobre os joelhos com a coluna neutra para apoiar os pesos no chão."],"errosComuns":["Deixar os ombros caírem para a frente e o pescoço projetado.","Dar passos largos rebolando o tronco de um lado ao outro.","Curvar a lombar ao pegar ou largar os halteres no chão."],"dicas":["Afaste levemente os pesos 2 centímetros das coxas para não bater nas pernas ao andar.","Imagine um fio puxando o topo da sua cabeça para o teto."],"respiracao":"Mantenha respiração curta e firme pelo nariz sem perder a pressão abdominal.","avisoSeguranca":"Mantenha postura firme, progrida a carga gradualmente e agache com as pernas ao pegar e soltar os pesos.","sinonimos":["farmer walk","farmers carry","fazendeiro","transporte de carga"],"grupo":"Funcional","subgrupo":"Força integrada","porTempo":true,"erroComum":"Deixar os ombros caírem para a frente e o pescoço projetado.","imagem":{"mini":null,"grande":null},"oculto":false,"duracaoSerieSeg":40},
{"id":"funcional-salto-caixa","nome":"Salto na caixa","noPlano":true,"equipamento":"Academia completa","equip":"degrau","equipamentoTipo":"Banco","musculoPrincipal":"Quadríceps","musculosSecundarios":["Glúteos","Panturrilhas"],"tipoMovimento":"agachar","composto":true,"passoCargaKg":0,"cargaBaseKg":0,"nivel":"Intermediário","cuidado":"Joelho","seriesPadrao":"4 × 8","descansoSeg":75,"descricao":"Salto pliométrico sobre caixa firme com aterrissagem suave para potência de membros inferiores.","comoFazer":["Fique a um passo de uma caixa pliométrica baixa ou média firme no piso.","Leve o quadril para trás e os braços ao lado do corpo em semiagachamento.","Salte impulsionando os dois pés e aterrisse com a planta inteira dos dois pés no centro da caixa.","Fique em pé no topo e DESÇA ANDANDO um pé de cada vez (nunca saltando de costas)."],"errosComuns":["Pular de costas da caixa para o chão, sobrecarregando o tendão de Aquiles.","Aterrissar apenas com a metade da frente dos pés na borda da caixa.","Escolher uma caixa alta demais que obrigue a encolher os joelhos no pescoço."],"dicas":["Escolha uma altura em que seu pouso no topo seja silencioso como um gato.","Descer um pé de cada vez preserva seus joelhos e tornozelos."],"respiracao":"Inspire ao armar o salto e solte o ar ao pousar firme sobre a caixa.","avisoSeguranca":"Use apenas caixa antiderrapante estável e desça sempre andando um pé de cada vez, nunca saltando para baixo.","sinonimos":["box jump","salto no caixote","pliometria na caixa"],"grupo":"Funcional","subgrupo":"Potência e agilidade","porTempo":false,"erroComum":"Pular de costas da caixa para o chão, sobrecarregando o tendão de Aquiles.","imagem":{"mini":null,"grande":null},"oculto":false},
{"id":"funcional-avanco-rotacao","nome":"Avanço com rotação","noPlano":true,"equipamento":"Em casa só com o corpo","equip":"solo-cruzado","equipamentoTipo":"Peso do corpo","musculoPrincipal":"Quadríceps","musculosSecundarios":["Oblíquos","Glúteos"],"tipoMovimento":"agachar","composto":true,"passoCargaKg":1,"cargaBaseKg":4,"nivel":"Iniciante","cuidado":"Joelho","seriesPadrao":"3 × 10","descansoSeg":45,"descricao":"Passada à frente combinada ao giro torácico sobre a perna da frente para pernas e core.","comoFazer":["Em pé, segure uma anilha leve, bola ou apenas una as mãos à frente do peito.","Dê um passo à frente e desça em afundo até os dois joelhos formarem cerca de 90 graus.","Estabilizado na base, gire o tronco suavemente para o MESMO lado da perna que está à frente.","Volte o tronco ao centro, empurre o chão para retornar em pé e alterne a perna."],"errosComuns":["Girar o tronco para o lado oposto da perna da frente e perder o equilíbrio.","Deixar o joelho da frente cair para dentro durante o giro.","Girar rápido dando tranco na coluna lombar."],"dicas":["Girar sempre em direção à coxa da frente fecha o quadril e ativa os oblíquos com estabilidade.","Pause meio segundo na base antes de iniciar a rotação."],"respiracao":"Inspire ao dar o passo e descer; expire enquanto gira o tronco sobre a perna da frente.","avisoSeguranca":"Estabilize primeiro o joelho da frente alinhado ao pé antes de girar suavemente a coluna torácica.","sinonimos":["lunge with twist","afundo com giro","passada com rotacao de tronco"],"grupo":"Funcional","subgrupo":"Força integrada","porTempo":false,"erroComum":"Girar o tronco para o lado oposto da perna da frente e perder o equilíbrio.","imagem":{"mini":null,"grande":null},"oculto":false},
{"id":"funcional-empurrar-treno","nome":"Empurrar trenó","noPlano":true,"equipamento":"Academia completa","equip":"maquina","equipamentoTipo":"Outros","musculoPrincipal":"Quadríceps","musculosSecundarios":["Glúteos","Panturrilhas","Reto abdominal"],"tipoMovimento":"empurrar","composto":true,"passoCargaKg":5,"cargaBaseKg":20,"nivel":"Intermediário","cuidado":"Joelho","seriesPadrao":"4 × 30 s","descansoSeg":60,"descricao":"Deslocamento potente empurrando o trenó em pista sintética para força de pernas sem fase excêntrica.","comoFazer":["Segure nas hastes verticais do trenó com os braços estendidos (ou cotovelos flexionados e firmes).","Incline o tronco a cerca de 45 graus mantendo uma linha reta da cabeça ao calcanhar de trás.","Dê passos firmes e contínuos empurrando o piso para trás com a parte anterior dos pés.","Mantenha o quadril baixo e constante durante todo o percurso."],"errosComuns":["Levantar o quadril e arredondar a coluna lombar olhando para o chão.","Dar passos curtos e saltitantes sem estender o joelho de trás.","Colocar carga excessiva que trave o trenó no meio da pista."],"dicas":["Mantenha os braços e o tronco rígidos para que 100% da força das pernas vá para o trenó.","Excelente estímulo de força e cardio que quase não gera dor muscular tardia."],"respiracao":"Mantenha respiração rítmica e potente a cada duas passadas.","avisoSeguranca":"Mantenha a postura firme em linha reta, progrida a carga gradualmente e confira se a pista está livre.","sinonimos":["sled push","prowler push","treno","empurrar prowler"],"grupo":"Funcional","subgrupo":"Potência e agilidade","porTempo":true,"erroComum":"Levantar o quadril e arredondar a coluna lombar olhando para o chão.","imagem":{"mini":null,"grande":null},"oculto":false,"duracaoSerieSeg":30}
